require dirname(__DIR__).'/app/bootstrap.php';if($argc<3){fwrite(STDERR,'Usage: php bin/create_admin.php email "Full Name"'.PHP_EOL);exit(1);}$email=strtolower(trim($argv[1]));$name=trim($argv[2]);if(!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($name)<2){exit("Invalid email or name.\n");}fwrite(STDOUT,'New unique password (14+ chars): ');$pw=trim(fgets(STDIN));if(strlen($pw)<14)exit("Password too short.\n");$q=$pdo->prepare("INSERT INTO users(name,email,password_hash,role_id,office_id) VALUES(?,?,?,(SELECT id FROM roles WHERE code='ADMIN'),(SELECT id FROM offices WHERE type='HO' LIMIT 1))");$q->execute([$name,$email,password_hash($pw,PASSWORD_DEFAULT)]);echo "Head Office administrator created.\n";
